CREATE TABLE user_credentials (                             -- global like users, no workspace_id
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  password_hash text,                                       -- argon2id, NULL for SSO-only users
  password_changed_at timestamptz,
  breached_checked_at timestamptz,
  failed_attempts smallint NOT NULL DEFAULT 0, locked_until timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);

